"""Assemble publication figures from NPZ files generated by synthetic_crosstalk.py.

Run from this directory after generating the eight default examples:
    python make_paper_figures.py
The script does not fit or apply a cross-talk correction.
"""
from pathlib import Path
import argparse
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.backends.backend_pdf import PdfPages
from synthetic_crosstalk import PRESETS, TITLES, plot_pair
from scipy.signal import convolve, convolve2d


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--input', type=Path, default=Path('examples'))
    parser.add_argument('--out', type=Path, default=Path('figures'))
    parser.add_argument('--n-show', type=int, default=7)
    args = parser.parse_args()
    args.out.mkdir(parents=True, exist_ok=True)
    plt.rcParams.update({'font.size': 9, 'axes.titlesize': 10, 'axes.labelsize': 9,
                         'legend.fontsize': 8, 'pdf.fonttype': 42, 'ps.fonttype': 42})
    data = {}
    for name in PRESETS:
        with np.load(args.input / f'{name}.npz', allow_pickle=False) as archive:
            data[name] = {key: archive[key] for key in archive.files}

    ####################### Filter Application #######################

    fig, axes = plt.subplots(
        3, 2, figsize=(8.5, 7), sharex=True, layout="constrained",# sharey="row"
    )
    for row, name in enumerate(("bipolar", "negative", "weak_bipolar")):
        d = data[name]
        source, target = d["source"], d["target"]
        nev, size = source.shape
        x = xt_filter(source, target, length=50)
        convolved = np.array([convolve(sig, x, mode="full") for sig in source])[:, :size]
    
        for i in range(2):
            ax = axes[row, i]
            #ax_s = ax.twinx()  # Separate scale keeps the target correction visible.
            #src, = ax_s.plot(
            #    d["time_us"], source[i], color="0.6", ls="--", lw=1, label="Source (right axis)"
            #)
            #ax_s.set_ylim(-0.15 * source[:2].max(), 1.15 * source[:2].max())
            #ax_s.tick_params(axis="y", colors="0.5", labelsize=8)
            #ax.set_zorder(ax_s.get_zorder() + 1)
            #ax.patch.set_visible(False)
    
            src, = ax.plot(d["time_us"], source[i]*0.3,"grey",ls="--",label="Source")
            raw, = ax.plot(d["time_us"], target[i], label="Target")
            corr, = ax.plot(d["time_us"], target[i]-convolved[i],"tab:red", label="Target corrected")
            ax.tick_params(direction="in", labelsize=8)
            ax.set_xlim(d["time_us"][0], d["time_us"][-1])
            ax.set_title(
                f"({chr(97 + 2 * row + i)}) {TITLES[name]} — event {i + 1}",
                loc="left", fontsize=9
            )
            ax.set_ylabel("Source / Target (a.u.)")
            if row == 2:
                ax.set_xlabel(r"Time ($\mu$s)")
    
    fig.legend(
        handles=[src, raw, corr], loc="outside upper center",
        ncol=3, frameon=False, fontsize=9
    )
    fig.savefig(args.out / "filter_applications.pdf", bbox_inches="tight")
    fig.savefig(args.out / 'filter_applications.png', dpi=200, bbox_inches='tight')
    plt.close(fig)

    ####################### Representative Pairs #######################

    fig, axes = plt.subplots(3, 2, figsize=(7.0, 6.5), sharex=True, layout='constrained')
    for row, name in enumerate(('bipolar', 'negative', 'weak_bipolar')):
        d = data[name]
        n = min(args.n_show, len(d['source']))
        for col, key in enumerate(('source', 'target')):
            ax = axes[row, col]
            for i in range(n):
                if key == "source":
                    ax.plot(d['time_us'], d[key][i], color=plt.get_cmap('tab20')(i % 20))
                else:
                    ax.plot(d['time_us'], d[key][i], color=plt.get_cmap('tab20')(i % 20),lw=0.8,alpha=0.8)
            ax.set_ylabel(f'{key.capitalize()} (a.u.)')
            ax.tick_params(direction='in', top=True, right=True)
            ax.set_xlim(d['time_us'][0], d['time_us'][-1])
            #ax.axhline(0, lw=0.5, color='0.5', zorder=0)
        axes[row, 0].set_title(f'({chr(97+row)}) {TITLES[name]}', loc='left')
        mean_ct = d['crosstalk_true'][:n].mean(0)
        axes[row, 1].plot(d['time_us'], mean_ct,'k--', lw=1.25, label='Mean cross-talk (truth)')
        axes[row, 1].set_ylim(min(-30,min(mean_ct)*1.65),max(30,max(mean_ct)*1.85))
        axes[row, 1].legend(loc="upper right")
    for ax in axes[-1]:
        ax.set_xlabel(r'Time ($\mu$s)')
    fig.savefig(args.out / 'representative_pairs.pdf', bbox_inches='tight')
    fig.savefig(args.out / 'representative_pairs.png', dpi=200, bbox_inches='tight')
    plt.close(fig)

    fig, axes = plt.subplots(2, 2, figsize=(7.0, 4.7), sharex=True, layout='constrained')
    for index, (ax, name) in enumerate(zip(axes.flat, ('positive', 'tail', 'ringing', 'echo'))):
        d = data[name]
        n = min(args.n_show, len(d['target']))
        for i in range(n):
            ax.plot(d['time_us'], d['target'][i], color=plt.get_cmap('tab20')(i % 20), lw=0.8, alpha=0.8)
        mean_ct = d['crosstalk_true'][:n].mean(0)
        ax.plot(d['time_us'], mean_ct, 'k--', lw=1.25, label='Mean cross-talk (truth)')
        ax.set_title(f'({chr(97+index)}) {TITLES[name]}', loc='left')
        ax.set_ylabel('Target (a.u.)')
        ax.set_xlim(d['time_us'][0], d['time_us'][-1])
        #ax.axhline(0, color='0.5', lw=0.5, zorder=0)
        ax.tick_params(direction='in', top=True, right=True)
        ax.set_ylim(min(-30,min(mean_ct)*1.65),max(30,max(mean_ct)*1.85))
        ax.legend(loc="upper right")
    for ax in axes[-1]:
        ax.set_xlabel(r'Time ($\mu$s)')
    fig.savefig(args.out / 'additional_responses.pdf', bbox_inches='tight')
    fig.savefig(args.out / 'additional_responses.png', dpi=200, bbox_inches='tight')
    plt.close(fig)

    with PdfPages(args.out / 'synthetic_crosstalk_examples.pdf') as pdf:
        for name in PRESETS:
            fig = plot_pair(data[name], TITLES[name], args.n_show)
            pdf.savefig(fig, bbox_inches='tight')
            plt.close(fig)
    print(f'Paper figures and eight-case gallery saved in {args.out}')


def xt_filter(source_signals, target_signals, length=50):
    n_ev, size = source_signals.shape
    mat = np.matmul(source_signals.T, source_signals, dtype=float)
    kernel = np.identity(size - length + 1)
    mat_fil = convolve2d(mat, kernel, boundary="symm", mode="valid")
    mat_stable = mat_fil + np.eye(mat_fil.shape[0]) * 1e-6
    ref_mat = np.matmul(target_signals.T, source_signals, dtype=float)
    ref = np.zeros(length, dtype=float)
    for i in range(size - length + 1):
        ref += ref_mat[i:i + length, i]
    return np.linalg.solve(mat_stable, ref).astype(np.float32)


if __name__ == '__main__':
    main()
